gdD(){return"\u10d3\u10d0\u10ef\u10d2\u10e3\u10e4\u10d4\u10d1\u10d0 \u10e1\u10d0\u10d7\u10d0\u10e3\u10e0\u10d8\u10d7"},
gdC(){return"\u10d3\u10d0\u10ef\u10d2\u10e3\u10e4\u10d4\u10d1\u10d0 \u10d0\u10e6\u10ec\u10d4\u10e0\u10d8\u10d7"},
gen(){return"\u10d3\u10d0\u10ef\u10d2\u10e3\u10e4\u10d4\u10d1\u10d0 \u10e1\u10d0\u10ee\u10d4\u10da\u10d8\u10d7"},
geo(){return"\u10d3\u10d0\u10efGrouping \u10de\u10dd\u10d6\u10d8\u10ea\u10d8\u10d8\u10d7"},
gdB(){return"\u10d0\u10db \u10d2\u10d0\u10dc\u10e7\u10dd\u10e4\u10d8\u10da\u10d4\u10d1\u10d0\u10e8\u10d8 \u10d0\u10e0\u10d0\u10e4\u10d4\u10e0\u10d8 \u10d8\u10de\u10dd\u10d5\u10d4\u10e1"},
