gdw(){return"\u10d9\u10d0\u10d5\u10e8\u10d8\u10e0\u10d8 \u10db\u10d8\u10db\u10d3\u10d8\u10dc\u10d0\u10e0\u10d4\u10dd\u10d1\u10e1"},
gcF(){return"\u10db\u10d4\u10e2\u10d8"},
gcE(){return"\u10dc\u10d0\u10d9\u10da\u10d4\u10d1\u10d8"},
