gdv(a){return"\u041f\u043e\u0442\u0432\u0440\u0434\u0438"},
gep(){return"\u041b\u043e\u0437\u0438\u043d\u043a\u0430\u0442\u0430 \u0438\u043b\u0438 \u043a\u043e\u0440\u0438\u0441\u043d\u0438\u0447\u043a\u043e\u0442\u043e \u0438\u043c\u0435 \u043d\u0435 \u0435 \u0432\u0430\u043b\u0438\u0434\u043d\u043e. \u0412\u0435 \u043c\u043e\u043b\u0438\u043c\u0435 \u043a\u043e\u043d\u0442\u0430\u043a\u0442\u0438\u0440\u0430\u0458\u0442\u0435 \u0433\u043e \u0432\u0430\u0448\u0438\u043e\u0442 \u043d\u0430\u0434\u0440\u0435\u0434\u0435\u043d"},
gec(){return"\u0412\u0435 \u043c\u043e\u043b\u0438\u043c\u0435 \u0432\u043d\u0435\u0441\u0435\u0442\u0435 \u0433\u043e \u043a\u043e\u0440\u0438\u0441\u043d\u0438\u0447\u043a\u043e\u0442\u043e \u0438\u043c\u0435 \u0438 \u043b\u043e\u0437\u0438\u043d\u043a\u0430\u0442\u0430 \u043f\u0440\u0430\u0432\u0438\u043b\u043d\u043e"},
