gdD(){return"\u0421\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043f\u043e \u0437\u0430\u0433\u043e\u043b\u043e\u0432\u043a\u0443"},
gdC(){return"\u0421\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043f\u043e \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u044e"},
gen(){return"\u0421\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043f\u043e \u0438\u043c\u0435\u043d\u0438"},
geo(){return"\u0421\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043f\u043e \u0434\u043e\u043b\u0436\u043d\u043e\u0441\u0442\u0438"},
gdB(){return"\u041d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u043e \u0432 \u044d\u0442\u043e\u043c \u0440\u0430\u0437\u0434\u0435\u043b\u0435"},
gcQ(a){return"\u041f\u043e\u0438\u0441\u043a"},
gdU(){return"\u0442\u043e\u043c\u0443 \u043d\u0430\u0437\u0430\u0434"},
ge5(){return"\u041f\u043e\u0434\u043a\u043b\u044e\u0447\u0438\u0442\u044c\u0441\u044f"},
gdw(){return"\u041f\u043e\u0434\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435"},
gcF(){return"\u0431\u043e\u043b\u044c\u0448\u0435"},
gcE(){return"\u043c\u0435\u043d\u044c\u0448\u0435"},
